 let productImportEpoch=0;
 async function readImport(file){if(!file)return;const epoch=++productImportEpoch;importProducts=[];$('#import-review').innerHTML='';try{if(!internal())throw Error('Hanya Admin atau Purchasing dapat mengimpor master produk');if(file.size>5*1024*1024)throw Error('File maksimal 5 MB');if(!window.XLSX)throw Error('Pembaca Excel belum tersedia. Periksa koneksi.');const data=await file.arrayBuffer();if(epoch!==productImportEpoch)return;const book=XLSX.read(data,{type:'array',raw:true}),rows=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{defval:'',raw:false});const products=M.parseProductImport(rows,S.data.suppliers,S.data.products);importProducts=products;const updated=products.filter(p=>S.data.products.some(x=>x.id===p.id)).length;$('#import-review').innerHTML=`<div class="format"><b>${esc(file.name)}</b><br>${products.length} produk · ${products.length-updated} baru · ${updated} diperbarui<br>Periksa kode, supplier dan konversi sebelum menyimpan. Tidak ada PO yang dibuat.</div><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama barang</th><th>Kelp-satuan</th><th>Kelp-volume</th><th>Suplier</th><th>Konversi</th></tr></thead><tbody>${products.slice(0,30).map(p=>`<tr><td>${esc(p.id)}</td><td>${esc(p.name)}</td><td>${esc(p.pack_units.join('-'))}</td><td>${p.pack_factors.join('-')}</td><td>${esc(supplier(p.supplier_id)?.name)}</td><td>${esc(packText(p))}</td></tr>`).join('')}</tbody></table></div><p class="sub">Menampilkan maksimal 30 baris pertama.</p>${button('Simpan Master Produk','PO.commitImport()',true)}`}catch(e){if(epoch!==productImportEpoch)return;importProducts=[];$('#import-review').innerHTML='';toast(e.message)}}
 async function commitImport(){if(!importProducts.length)return;const result=await command('master_products',{entries:importProducts},'Master produk dan konversi kemasan tersimpan.');if(result){importProducts=[];S.page='products';render()}}
 function renderUnitControl(row,p,unit){const value=String(unit||p?.unit||'PCS').toUpperCase();if(p){const pack=M.productPack(p),valid=pack.units.includes(value);row.querySelector('.item-unit-control').innerHTML=`<select class="item-unit" required onchange="PO.updateConversion(this.closest('.draft-item'))">${!valid?'<option value="" selected>Pilih satuan produk saat ini</option>':''}${pack.units.map(u=>`<option value="${esc(u)}" ${u===value?'selected':''}>${esc(u)}</option>`).join('')}</select>`}else row.querySelector('.item-unit-control').innerHTML=`<input class="item-unit" value="${esc(value)}" maxlength="30" oninput="PO.updateConversion(this.closest('.draft-item'))" required>`;updateConversion(row)}
 function addItem(value={}){const form=$('#draft-form');if(!form)return;const products=S.data.products.filter(p=>p.supplier_id===form.elements.supplier.value),p=products.find(p=>p.id===value.product_code);const row=document.createElement('div');row.className='draft-item';row.innerHTML=`<div class="form-group"><label>Produk master (opsional)</label><select class="item-product" onchange="PO.pickProduct(this)"><option value="">Barang manual</option>${products.map(p=>`<option value="${esc(p.id)}" ${value.product_code===p.id?'selected':''}>${esc(p.id)} - ${esc(p.name)}</option>`).join('')}</select><label class="item-code-label">Kode barang</label><input class="item-code" aria-label="Kode barang" value="${esc(p?.id||value.product_code||'')}" placeholder="Tanpa kode (barang manual)" readonly></div><div class="form-group"><label>Nama barang</label><input class="item-name" value="${esc(value.name||'')}" maxlength="120" required></div><div class="form-group"><label>Qty pesanan</label><input class="item-qty" type="number" min="1" max="10000000" step="1" value="${value.qty||1}" oninput="PO.updateConversion(this.closest('.draft-item'))" required></div><div class="form-group"><label>Satuan</label><div class="item-unit-control"></div></div><button type="button" class="text-link" onclick="this.closest('.draft-item').remove()">Hapus</button><small class="pack-hint"></small>`;$('#draft-items').append(row);renderUnitControl(row,p,value.unit)}
 function pickProduct(select){const p=S.data.products.find(p=>p.id===select.value),row=select.closest('.draft-item');if(p)row.querySelector('.item-name').value=p.name;row.querySelector('.item-code').value=p?.id||'';renderUnitControl(row,p,p?.unit||row.querySelector('.item-unit')?.value||'PCS')}
 function updateConversion(row){const p=S.data.products.find(p=>p.id===row.querySelector('.item-product').value),hint=row.querySelector('.pack-hint');if(!p){hint.textContent='';return}const pack=M.productPack(p),unit=row.querySelector('.item-unit').value,idx=pack.units.indexOf(unit),qty=Number(row.querySelector('.item-qty').value);hint.textContent=idx>=0&&Number.isInteger(qty)&&qty>0?`${qty} ${unit} = ${qty*pack.factors[idx]} ${pack.baseUnit}`:'Pilih satuan dan isi qty pesanan.'}
