 async function exportImage(id,page){
  const o=order(id);if(!o)return;
  const rows=items(o.id),pageSize=20,pages=Math.max(1,Math.ceil(rows.length/pageSize));
  if(pages>1&&page===undefined){modal('<h2>Unduh gambar PO</h2><p class="sub">PO ini dibagi menjadi '+pages+' gambar, maksimal 20 barang per gambar. Pilih halaman yang ingin disimpan.</p><div class="buttons">'+Array.from({length:pages},(_,i)=>button('Halaman '+(i+1),"PO.exportImage('"+o.id+"',"+i+")")).join('')+'<button class="btn" onclick="PO.close()">Tutup</button></div>');return}
  page=page??0;if(!Number.isInteger(page)||page<0||page>=pages)return;
  try{await opening(async()=>{
   const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d'),widths=[140,360,110,120,270],margin=32,line=25;
   ctx.font='18px Arial';
   function wrap(value,width){const lines=[];let text='';for(const char of String(value??'-')){if(char==='\n'){lines.push(text);text='';continue}if(text&&ctx.measureText(text+char).width>width){lines.push(text);text=char}else text+=char}lines.push(text);return lines}
   const selected=rows.slice(page*pageSize,(page+1)*pageSize),locked=qtyLocked(o);
   const cells=selected.map(i=>[i.product_code||'-',i.name,i.unit,locked?'Terkunci':i.qty??'-',locked?'Terkunci':String(i.base_qty??i.qty??'-')+' '+(i.base_unit||i.unit)]);
   const headers=['Kode','Nama barang','Satuan','Qty','Setara satuan dasar'];
   const grid=[headers,...cells].map(row=>{const parts=row.map((v,i)=>wrap(v,widths[i]-20));return {parts,height:Math.max(...parts.map(x=>x.length))*line+22}});
   const meta=['PO: '+o.number,'Supplier: '+(supplier(o.supplier_id)?.name||o.supplier_id),'Tanggal: '+date(o.order_date)+' | Status: '+M.labels[o.status],'Estimasi pengantaran: '+(o.eta?date(o.eta):'Belum diisi'),...(locked?['Qty terkunci sampai PO dikonfirmasi dan estimasi pengantaran diisi.']:[])].flatMap(t=>wrap(t,1000));
   const top=100+meta.length*line+24;
   canvas.width=1064;canvas.height=top+grid.reduce((n,r)=>n+r.height,0)+75;
   ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#991b1b';ctx.font='bold 30px Arial';ctx.fillText('KEDAI UPU - PURCHASE ORDER',margin,55);
   ctx.fillStyle='#334155';ctx.font='18px Arial';meta.forEach((t,i)=>ctx.fillText(t,margin,100+i*line));
   let y=top;
   grid.forEach((row,r)=>{let x=margin;row.parts.forEach((lines,c)=>{ctx.fillStyle=r===0?'#e8edf3':r%2?'#ffffff':'#f5f7fa';ctx.fillRect(x,y,widths[c],row.height);ctx.strokeStyle='#aeb8c5';ctx.lineWidth=1;ctx.strokeRect(x,y,widths[c],row.height);ctx.fillStyle='#172033';ctx.font=r===0?'bold 18px Arial':'18px Arial';lines.forEach((t,j)=>ctx.fillText(t,x+10,y+29+j*line));x+=widths[c]});y+=row.height});
   ctx.font='16px Arial';ctx.fillStyle='#64748b';ctx.fillText('Halaman '+(page+1)+' / '+pages+' | '+selected.length+' barang',margin,y+40);
   const dataUrl=canvas.toDataURL('image/png'),name=o.number.replace(/[^A-Za-z0-9_-]/g,'_')+(pages>1?'-'+(page+1):'')+'.png';
   if(window.NativeFiles){if(!window.NativeFiles.saveImage)throw Error('Perbarui APK untuk menyimpan gambar PO.');await window.NativeFiles.saveImage(name,dataUrl)}
   else{const link=document.createElement('a');link.href=dataUrl;link.download=name;link.click()}
  })}catch(e){toast(e.message||'Gambar belum dapat disimpan. Coba lagi.')}
 }
 function exportOrders(id){const list=id?S.data.orders.filter(o=>o.id===id):filtered(),quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';return download('purchase-orders.csv','\ufeff'+[['Nomor PO','Tanggal','Supplier','Status','Estimasi','Kode Barang','Barang','Qty','Satuan'],...list.flatMap(o=>items(o.id).map(i=>[o.number,o.order_date,supplier(o.supplier_id)?.name,M.labels[o.status],o.eta||'',i.product_code||'',i.name,qtyLocked(o)?'Terkunci':i.qty,i.unit]))].map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv')}
 function poImportPage(){if(!internal())return go('dashboard');$('#main').innerHTML=heading('Import PO','Buat Draft PO per supplier. Periksa terlebih dahulu sebelum menerbitkannya.')+`<section class="panel import-box"><h2>Unggah daftar barang</h2><p class="sub">Kolom: supplier, nama_produk, qty, satuan. Supplier harus sudah dibuat Admin. Maksimal 5 MB, 10.000 baris, 100 supplier.</p><input type="file" accept=".csv,.xlsx,.xls" onchange="PO.readPOImport(this.files[0])"><div id="import-review"></div></section>`}
 async function readPOImport(file){if(!file)return;try{if(file.size>5*1024*1024)throw Error('File maksimal 5 MB');if(!window.XLSX)throw Error('Pembaca Excel belum tersedia. Periksa koneksi.');const book=XLSX.read(await file.arrayBuffer(),{type:'array'}),rows=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{defval:''});if(!rows.length||rows.length>10000)throw Error('File harus berisi 1–10.000 baris');const groups=new Map();for(const [index,row] of rows.entries()){const code=String(row.supplier||'').trim(),matches=S.data.suppliers.filter(s=>s.active&&(s.id===code||s.name===code));if(matches.length!==1)throw Error('Baris '+(index+2)+': gunakan kode supplier aktif yang unik');const s=matches[0],item={name:String(row.nama_produk||'').trim(),qty:Number(row.qty),unit:String(row.satuan||'').trim()};M.validateItems([item]);if(!groups.has(s.id))groups.set(s.id,[]);groups.get(s.id).push(item)}if(groups.size>100)throw Error('Maksimal 100 supplier per impor');importOrders=[...groups].map(([supplier_id,items])=>({supplier_id,items,request_id:crypto.randomUUID(),order_date:M.today(),note:'Import '+file.name,publish:false}));$('#import-review').innerHTML=`<div class="format"><b>${esc(file.name)}</b><br>${rows.length} barang · ${groups.size} Draft PO</div><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Barang</th><th>Qty</th></tr></thead><tbody>${importOrders.map(o=>`<tr><td>${esc(supplier(o.supplier_id).name)}</td><td>${o.items.length}</td><td>${o.items.reduce((n,i)=>n+i.qty,0)}</td></tr>`).join('')}</tbody></table></div>${button('Simpan semua sebagai Draft','PO.commitPOImport()',true)}`}catch(e){importOrders=[];$('#import-review').innerHTML='';toast(e.message)}}
 async function commitPOImport(){if(!importOrders.length)return;const data=await command('draft_batch',{orders:importOrders},'Draft PO hasil impor tersimpan.');if(data){importOrders=[];S.page='orders';render()}}
 async function login(form){const submit=form.querySelector('button');submit.disabled=true;try{const {data,error}=await client.auth.signInWithPassword({email:form.elements.email.value.trim(),password:form.elements.password.value});if(error)throw error;form.reset();S.session=data.session;await load()}catch{$('#login-error').textContent='Login gagal. Periksa email, kata sandi, dan koneksi.'}finally{submit.disabled=false}}
